def parse_version(text: str) -> tuple[int, int, int]:
    parts = text.strip().split('.')
    if len(parts) != 3:
        raise ValueError(f"expected 3 dot-separated segments, got {len(parts)}: {text!r}")
    numbers = []
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"version segment is not a pure number: {part!r}")
        numbers.append(int(part))
    return numbers[0], numbers[1], numbers[2]
